  "source": "def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_op, channel_type, trigger):
        committed = {}
        main_tx = None
        other_tx = None
        total_changes_main = 0
        total_changes_other = 0
        last_changes_main = 0

        def get_effective(conn):
            if conn == 'main':
                tx = main_tx
            else:
                tx = other_tx
            if tx is None:
                return dict(committed)
            eff = dict(committed)
            for k, v in tx.items():
                if v is None:
                    if k in eff:
                        del eff[k]
                else:
                    eff[k] = v
            return eff

        def apply_put(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            exists = key in eff
            changes = 0
            if put_op == 'ignore':
                if not exists:
                    changes = 1
                    if conn == 'main':
                        if main_tx is not None:
                            main_tx[key] = value
                        else:
                            committed[key] = value
                    else:
                        if other_tx is not None:
                            other_tx[key] = value
                        else:
                            committed[key] = value
            elif put_op == 'replace':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            elif put_op == 'upsert':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes
            if trigger and changes > 0:
                if conn == 'main':
                    total_changes_main += 1
                else:
                    total_changes_other += 1

        def apply_update(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        def apply_delete(conn, key):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
                else:
                    if other_tx is not None:
                        other_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        for action in actions:
            op = action.get('op')
            conn = action.get('connection', 'main')
            if op == 'put':
                apply_put(conn, action['key'], action['value'])
            elif op == 'update':
                apply_update(conn, action['key'], action['value'])
            elif op == 'delete':
                apply_delete(conn, action['key'])
            elif op == 'begin':
                if conn == 'main':
                    main_tx = {}
                else:
                    other_tx = {}
            elif op == 'commit':
                if conn == 'main':
                    if main_tx is not None:
                        for k, v in main_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        main_tx = None
                else:
                    if other_tx is not None:
                        for k, v in other_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        other_tx = None
            elif op == 'rollback':
                if conn == 'main':
                    main_tx = None
                else:
                    other_tx = None

        if channel_type == 'changes':
            channel = last_changes_main
        elif channel_type == 'total_main':
            channel = total_changes_main
        else:
            channel = total_changes_main + total_changes_other

        committed_count = len(committed)
        committed_sum = sum(committed.values())
        return channel, committed_count, committed_sum

    put_ops = ['ignore', 'replace', 'upsert']
    channel_types = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    consistent = []
    for put_op in put_ops:
        for channel_type in channel_types:
            for trigger in triggers:
                ok = True
                for receipt in history:
                    actions = receipt['actions']
                    observed = receipt['observed']
                    ch, cc, cs = simulate(actions, put_op, channel_type, trigger)
                    if ch != observed['channel'] or cc != observed['committed_count'] or cs != observed['committed_sum']:
                        ok = False
                        break
                if ok:
                    consistent.append((put_op, channel_type, trigger))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context['goal']
    actions = context['actions']

    results = set()
    for put_op, channel_type, trigger in consistent:
        ch, cc, cs = simulate(actions, put_op, channel_type, trigger)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    else:
        return {"value": None, "unresolved": True}",
  "scope": "Predicts channel, committed_count, and committed_sum for any sequence of up to 32 actions on a fresh database, given the source's put operation is INSERT OR REPLACE and the channel is main total_changes plus other total_changes, with an AFTER INSERT trigger that logs one row per insert.",
  "lesson": "The channel is main total_changes plus other total_changes, the put operation is INSERT OR REPLACE, and there is an AFTER INSERT trigger that logs one row per insert. The committed state is the final state after all actions, with uncommitted transactions discarded. The channel counts every row change including those in uncommitted transactions and trigger inserts."
}
